script:
card({ name: "Scoreboard", icon: 'trophy' });
const words = {
  teamA: "Team A",
  teamB: "Team B",
  addTeam: "Add a team",
  reset: "Reset scores",
  full: "Eight teams at most",
  gone: "That team is gone",
  onlySender: "Only the person who sent the card can do that",
};

// Points for each team. Anyone in the chat can score; only the sender
// can reset.
function init() {
  return { teams: [{ name: words.teamA, score: 0 }, { name: words.teamB, score: 0 }] };
}

on.score = (s, args) => {
  const t = s.teams[args.team];
  if (!t) throw words.gone;
  t.score += args.by;
};

on.addTeam = (s, args) => {
  const name = String(args.value || '').trim().slice(0, 30);
  if (!name) return;
  if (s.teams.length >= 8) throw words.full;
  s.teams.push({ name, score: 0 });
};

on.reset = (s, args, ctx) => {
  if (ctx.author !== ctx.sender) throw words.onlySender;
  for (const t of s.teams) t.score = 0;
};

function view(s, me) {
  const top = s.teams.reduce((m, t) => Math.max(m, t.score), 0);
  return column([
    ...s.teams.map((t, i) => row([
      text((top > 0 && t.score === top ? '🏆 ' : '') + t.name, { bold: true }),
      row([
        text(String(t.score), { size: 'large', bold: true, tone: top > 0 && t.score === top ? 'accent' : undefined }),
        button('−1', 'score', { team: i, by: -1 }),
        button('+1', 'score', { team: i, by: 1 }, { tone: 'accent' }),
      ]),
    ], { align: 'between' })),
    divider(),
    input('team', words.addTeam, 'addTeam'),
    me.isSender && button(words.reset, 'reset', null, { tone: 'muted', align: 'center' }),
  ]);
}
